import * as T from 'three';
export function createManeuverNode(preview,time){if(Math.abs(preview.deltaV)<.5)throw Error('固定するΔvは0.5 m/s以上にしてください');return {universalTime:preview.universalTime,time:time+preview.time,position:preview.burnPos.toArray(),velocity:preview.afterVel.toArray(),impulse:preview.impulse.toArray(),remaining:preview.impulse.toArray(),complete:false};}
export function maneuverDirection(node){return node?new T.Vector3(...(node.complete?node.impulse:node.remaining)).normalize():null;}
export function advanceManeuver(node,engineDeltaV){if(!node)return;const before=new T.Vector3(...node.remaining),fraction=engineDeltaV.lengthSq()?Math.max(0,Math.min(1,before.dot(engineDeltaV)/engineDeltaV.lengthSq())):0,closest=before.clone().addScaledVector(engineDeltaV,-fraction),remaining=before.sub(engineDeltaV);node.remaining=remaining.toArray();node.complete=node.complete||closest.length()<.5;}
export function validateManeuverNode(value){if(value==null)return null;if(value.universalTime!==undefined&&(!Number.isFinite(value.universalTime)||value.universalTime<0||value.universalTime>1e12))throw Error('マニューバ時刻が不正です');const validArray=(a,limit)=>Array.isArray(a)&&a.length===3&&a.every(v=>Number.isFinite(v)&&Math.abs(v)<=limit);if(!Number.isFinite(value.time)||value.time<0||value.time>1e12||typeof value.complete!=='boolean'||!validArray(value.position,1e10)||!validArray(value.velocity,1e6)||!validArray(value.impulse,10000)||!validArray(value.remaining,1e6)||(new T.Vector3(...value.impulse).length()<.5||new T.Vector3(...value.impulse).length()>10000.001)||(!value.complete&&new T.Vector3(...value.remaining).length()<.5))throw Error('マニューバ計画の保存値が不正です');if(value.capture!==undefined){const c=value.capture;if(!c||!Number.isFinite(value.universalTime)||!['midTime','duration','deltaV','periapsis'].every(k=>Number.isFinite(c[k]))||c.duration<=0||c.duration>1200||c.deltaV<.5||c.deltaV>10000||c.periapsis<1000||c.periapsis>2500000||Math.abs(c.midTime-value.universalTime-c.duration/2)>.001||Math.abs(c.deltaV-new T.Vector3(...value.impulse).length())>.001)throw Error('月周回計画の保存値が不正です');}if(value.returnPlan!==undefined){const r=value.returnPlan;if(r?.targetPeriapsis!==undefined&&(!Number.isFinite(r.targetPeriapsis)||r.targetPeriapsis<10000||r.targetPeriapsis>=70000))throw Error('帰還目標近点の保存値が不正です');if(value.capture!==undefined||!r||!Number.isFinite(value.universalTime)||!['midTime','duration','deltaV','predictedPeriapsis','exitTime'].every(k=>Number.isFinite(r[k]))||r.duration<=0||r.duration>1200||r.deltaV<.5||r.deltaV>10000||r.predictedPeriapsis<10000||r.predictedPeriapsis>=70000||r.exitTime<=r.midTime||r.exitTime-r.midTime>604800||Math.abs(r.midTime-value.universalTime-r.duration/2)>.001||Math.abs(r.deltaV-new T.Vector3(...value.impulse).length())>.001)throw Error('母星帰還計画の保存値が不正です');}return structuredClone(value);}
